What is the output of the following program?

#include <stdio.h>
#include <string.h>
int main(void) {
    char str1[20] = "Hello";
    char str2[] = "World";
    strcat(str1, str2);
    printf("%zu", strlen(str1));
    return 0;
}

What will be the output of this recursive function call print_rec(3)?

void print_rec(int n) {
    if (n <= 0) return;
    print_rec(n - 1);
    printf("%d ", n);
}

What is the output of the following program?

#include <stdio.h>
void count(void) {
    static int c = 0;
    c++;
    printf("%d ", c);
}
int main(void) {
    count();
    count();
    count();
    return 0;
}

What is the output of the following C code?

#include <stdio.h>
int main(void) {
    int x = 10, y = 20;
    int *p = &x;
    *p = 30;
    p = &y;
    *p = 40;
    printf("%d %d", x, y);
    return 0;
}

